import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  sessions: defineTable({
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  }).index("by_active_expires", ["isActive", "expiresAt"]),
});

import { mutation, query } from "convex/server";
import { v } from "convex/values";

export const createSession = mutation({
  args: {
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  },
  handler: async (ctx, args) => {
    const id = await ctx.db.insert("sessions", args);
    return id;
  },
});

export const getSession = query({
  args: { id: v.id("sessions") },
  handler: async (ctx, args) => {
    return await ctx.db.get(args.id);
  },
});

export const cleanupExpiredSessions = mutation({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const expiredSessions = await ctx.db
      .query("sessions")
      .withIndex("by_active_expires", (q) =>
        q.eq("isActive", true).lt("expiresAt", now)
      )
      .collect();

    for (const session of expiredSessions) {
      await ctx.db.patch(session._id, { isActive: false });
    }

    return { updatedCount: expiredSessions.length };
  },
});

import { cronJobs } from "convex/server";

const crons = cronJobs();

crons.interval(
  "cleanup expired sessions",
  { minutes: 1 },
  "sessions:cleanupExpiredSessions"
);

export default crons;

const { ConvexHttpClient } = require("convex/browser");

function getArgValue(flag) {
  const index = process.argv.indexOf(flag);
  if (index === -1 || index + 1 >= process.argv.length) {
    return null;
  }
  return process.argv[index + 1];
}

async function main() {
  const runId = getArgValue("--run-id");
  if (!runId) {
    throw new Error("Missing --run-id argument.");
  }

  const convexUrl = process.env.CONVEX_URL;
  if (!convexUrl) {
    throw new Error("CONVEX_URL environment variable is required.");
  }

  const client = new ConvexHttpClient(convexUrl);
  const deployKey = process.env.CONVEX_DEPLOY_KEY;
  if (deployKey) {
    client.setAdminAuth(deployKey);
  }

  const sessionId = await client.mutation("sessions:createSession", {
    runId,
    expiresAt: Date.now() - 60_000,
    isActive: true,
  });

  console.log(`Session ID: ${sessionId}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

